INSERT INTO quizz.quiz_questions (category, question, option_a, option_b, option_c, option_d, correct_option, created_at) VALUES ('basic', 'Dlaczego cyberbezpieczeństwo jest ważne?', 'Chroni przed zagrożeniami fizycznymi', 'Zapewnia ochronę danych i systemów komputerowych', 'Eliminuje potrzebę stosowania haseł', 'Gwarantuje brak wirusów w Internecie', 'b', '2025-01-03 17:58:18');
INSERT INTO quizz.quiz_questions (category, question, option_a, option_b, option_c, option_d, correct_option, created_at) VALUES ('basic', 'Co to jest malware?', 'Rodzaj bezpiecznego oprogramowania', 'Oprogramowanie szpiegujące lub uszkadzające dane', 'System operacyjny', 'Metoda szyfrowania danych', 'b', '2025-01-03 17:58:18');
INSERT INTO quizz.quiz_questions (category, question, option_a, option_b, option_c, option_d, correct_option, created_at) VALUES ('basic', 'Jakie są podstawowe zasady ochrony danych osobowych?', 'Używanie jednolitego hasła do wszystkich kont', 'Udostępnianie danych osobowych na żądanie', 'Minimalizacja danych, regularne aktualizacje', 'Przechowywanie danych wyłącznie na dyskach zewnętrznych', 'c', '2025-01-03 17:58:18');
INSERT INTO quizz.quiz_questions (category, question, option_a, option_b, option_c, option_d, correct_option, created_at) VALUES ('basic', 'Jakie są zasady tworzenia silnych haseł?', 'Hasło powinno być krótkie i proste', 'Hasło powinno zawierać kombinację liter, cyfr i znaków specjalnych', 'Hasło powinno być imieniem użytkownika', 'Hasło powinno być takie same jak PIN karty', 'b', '2025-01-03 17:58:18');
INSERT INTO quizz.quiz_questions (category, question, option_a, option_b, option_c, option_d, correct_option, created_at) VALUES ('basic', 'Co oznacza termin phishing?', 'Ochrona przed wirusami', 'Wyłudzanie danych osobowych za pomocą fałszywych wiadomości', 'Szyfrowanie danych', 'Atak na serwery', 'b', '2025-01-03 17:58:18');
INSERT INTO quizz.quiz_questions (category, question, option_a, option_b, option_c, option_d, correct_option, created_at) VALUES ('basic', 'Jak zabezpieczyć urządzenia mobilne?', 'Instalować aplikacje tylko z oficjalnych sklepów', 'Wyłączyć wszystkie aktualizacje', 'Korzystać z darmowych sieci Wi-Fi bez zabezpieczeń', 'Nie używać haseł do blokady ekranu', 'a', '2025-01-03 17:58:18');
INSERT INTO quizz.quiz_questions (category, question, option_a, option_b, option_c, option_d, correct_option, created_at) VALUES ('basic', 'Czym jest ransomware?', 'Rodzaj aplikacji do zarządzania danymi', 'Oprogramowanie blokujące dostęp do danych i żądające okupu', 'Program antywirusowy', 'Metoda ochrony sieci', 'b', '2025-01-03 17:58:18');
INSERT INTO quizz.quiz_questions (category, question, option_a, option_b, option_c, option_d, correct_option, created_at) VALUES ('basic', 'Jak rozpoznać bezpieczną stronę internetową?', 'Adres zaczyna się od "http://"', 'Adres zaczyna się od "https://" i posiada certyfikat SSL', 'Strona ma kolorowe tło', 'Strona nie wymaga logowania', 'b', '2025-01-03 17:58:18');
INSERT INTO quizz.quiz_questions (category, question, option_a, option_b, option_c, option_d, correct_option, created_at) VALUES ('basic', 'Dlaczego aktualizacje oprogramowania są ważne?', 'Dodają nowe funkcje do programów', 'Usuwają znane luki w zabezpieczeniach', 'Zmniejszają wydajność systemu', 'Sprawiają, że system jest mniej stabilny', 'b', '2025-01-03 17:58:18');
INSERT INTO quizz.quiz_questions (category, question, option_a, option_b, option_c, option_d, correct_option, created_at) VALUES ('basic', 'Co oznacza pojęcie "zapora ogniowa"?', 'Fizyczna blokada urządzenia', 'Oprogramowanie lub urządzenie filtrujące ruch sieciowy', 'Program do odzyskiwania danych', 'Narzędzie do kompresji plików', 'b', '2025-01-03 17:58:18');
