INSERT INTO quizz.quiz_questions (category, question, option_a, option_b, option_c, option_d, correct_option, created_at) VALUES ('medium', 'Co oznacza skrót GDPR?', 'General Data Protection Regulation', 'General Development Program Rules', 'Global Data Policy Regulations', 'Governmental Data Protection Requirements', 'a', '2025-01-03 18:01:09');
INSERT INTO quizz.quiz_questions (category, question, option_a, option_b, option_c, option_d, correct_option, created_at) VALUES ('medium', 'Jak można zabezpieczać sieci wewnętrzne?', 'Wyłączanie zapory ogniowej', 'Używanie VPN i segmentacja sieci', 'Zablokowanie dostępu do wszystkich stron internetowych', 'Instalacja oprogramowania do udostępniania plików', 'b', '2025-01-03 18:01:09');
INSERT INTO quizz.quiz_questions (category, question, option_a, option_b, option_c, option_d, correct_option, created_at) VALUES ('medium', 'Jakie są podstawowe zasady bezpieczeństwa w pracy zdalnej?', 'Używanie publicznych sieci Wi-Fi', 'Korzystanie z VPN oraz aktualizowanego oprogramowania', 'Udostępnianie haseł współpracownikom', 'Wyłączanie antywirusa na czas pracy', 'b', '2025-01-03 18:01:09');
