INSERT INTO quizz.quiz_questions (category, question, option_a, option_b, option_c, option_d, correct_option, created_at) VALUES ('medium', 'Jakie są konsekwencje niezgodności z GDPR?', 'Kara finansowa i utrata reputacji', 'Utrata danych osobowych', 'Blokada dostępu do Internetu', 'Przymus zmiany oprogramowania', 'a', '2025-01-03 18:01:09');
INSERT INTO quizz.quiz_questions (category, question, option_a, option_b, option_c, option_d, correct_option, created_at) VALUES ('medium', 'Jak działa IDS (Intrusion Detection System)?', 'Blokuje podejrzany ruch sieciowy', 'Monitoruje sieć i identyfikuje potencjalne zagrożenia', 'Tworzy kopie zapasowe danych', 'Przyspiesza działanie aplikacji', 'b', '2025-01-03 18:01:09');
INSERT INTO quizz.quiz_questions (category, question, option_a, option_b, option_c, option_d, correct_option, created_at) VALUES ('advanced', 'Co to jest exploit development?', 'Proces wykrywania luk w oprogramowaniu i ich wykorzystania', 'Tworzenie bezpiecznych aplikacji', 'Ochrona danych osobowych', 'Skanowanie sieci w poszukiwaniu zagrożeń', 'a', '2025-01-03 18:07:57');
INSERT INTO quizz.quiz_questions (category, question, option_a, option_b, option_c, option_d, correct_option, created_at) VALUES ('advanced', 'Jakie narzędzia służą do analizy zagrożeń?', 'Wireshark, Snort, Splunk', 'Excel i Word', 'Przeglądarki internetowe', 'Programy do tworzenia kopii zapasowych', 'a', '2025-01-03 18:07:57');
INSERT INTO quizz.quiz_questions (category, question, option_a, option_b, option_c, option_d, correct_option, created_at) VALUES ('advanced', 'Jakie są kluczowe kroki w reagowaniu na incydenty?', 'Ignorowanie zgłoszenia, aby nie wywoływać paniki', 'Identyfikacja, izolacja, analiza, usunięcie zagrożenia', 'Automatyczne usunięcie wszystkich plików', 'Zrestartowanie wszystkich urządzeń', 'b', '2025-01-03 18:07:57');
INSERT INTO quizz.quiz_questions (category, question, option_a, option_b, option_c, option_d, correct_option, created_at) VALUES ('advanced', 'Jak zabezpieczać aplikacje webowe?', 'Regularne aktualizacje i stosowanie mechanizmów uwierzytelniania', 'Usunięcie wszystkich zabezpieczeń', 'Przechowywanie danych w formacie niezaszyfrowanym', 'Wyłączenie logowania użytkowników', 'a', '2025-01-03 18:07:57');
INSERT INTO quizz.quiz_questions (category, question, option_a, option_b, option_c, option_d, correct_option, created_at) VALUES ('advanced', 'Co oznacza termin inżynieria wsteczna?', 'Tworzenie oprogramowania od podstaw', 'Analiza istniejącego oprogramowania w celu poznania jego struktury i działania', 'Kopiowanie plików z jednego systemu na drugi', 'Szyfrowanie danych', 'b', '2025-01-03 18:07:57');
