INSERT INTO quizz.quiz_questions (category, question, option_a, option_b, option_c, option_d, correct_option, created_at) VALUES ('advanced', 'Jak działa SIEM (Security Information and Event Management)?', 'Monitoruje i analizuje zdarzenia bezpieczeństwa w czasie rzeczywistym', 'Tworzy kopie zapasowe danych', 'Optymalizuje działanie aplikacji', 'Wyłącza podejrzane urządzenia', 'a', '2025-01-03 18:07:57');
INSERT INTO quizz.quiz_questions (category, question, option_a, option_b, option_c, option_d, correct_option, created_at) VALUES ('advanced', 'Jakie są techniki obrony przed inżynierią wsteczną?', 'Szyfrowanie kodu i stosowanie obfuskacji', 'Publiczne udostępnienie kodu źródłowego', 'Automatyczne generowanie dokumentacji', 'Brak zabezpieczeń w oprogramowaniu', 'a', '2025-01-03 18:07:57');
INSERT INTO quizz.quiz_questions (category, question, option_a, option_b, option_c, option_d, correct_option, created_at) VALUES ('advanced', 'Co oznacza termin "threat hunting"?', 'Aktywne wyszukiwanie zagrożeń w systemie', 'Tworzenie kopii zapasowych danych', 'Blokowanie wszystkich połączeń sieciowych', 'Automatyczne aktualizacje oprogramowania', 'a', '2025-01-03 18:07:57');
INSERT INTO quizz.quiz_questions (category, question, option_a, option_b, option_c, option_d, correct_option, created_at) VALUES ('advanced', 'Jakie są zalety stosowania izolowanych środowisk testowych (sandbox)?', 'Umożliwiają bezpieczne testowanie oprogramowania', 'Przyspieszają działanie systemu operacyjnego', 'Blokują wszystkie połączenia internetowe', 'Zmniejszają koszty licencji', 'a', '2025-01-03 18:07:57');
